import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 9
    header_rows = 3

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"",
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    def is_date_value(value):
        return bool(re.match(r"^\s*\d{1,4}[/-]\d{1,2}[/-]\d{1,4}\s*$", value or ""))

    def normalize(values, width=expected_width):
        values = ["" if value is None else str(value) for value in values]
        if len(values) < width:
            return values + [""] * (width - len(values))
        if len(values) > width:
            return values[:width - 1] + [",".join(values[width - 1:])]
        return values

    def flatten_header(parts):
        flattened = []
        for part in parts:
            flattened.extend(part)
        return normalize(flattened)

    header_start = None

    for i in range(max(0, len(records) - header_rows)):
        group = records[i:i + header_rows]
        if len(group) != header_rows:
            continue
        if sum(len(row) for row in group) != expected_width:
            continue
        following = records[i + header_rows:]
        if any(row and is_date_value(row[0]) for row in following):
            header_start = i
            break

    if header_start is None:
        first_data = next(
            (i for i, row in enumerate(records) if row and is_date_value(row[0])),
            None,
        )
        if first_data is not None and first_data >= header_rows:
            header_start = first_data - header_rows
        else:
            header_start = next(
                (
                    i for i in range(len(records))
                    if len(records[i]) == expected_width
                ),
                0,
            )

    header_parts = records[header_start:header_start + header_rows]
    columns = flatten_header(header_parts)

    data_start = header_start + header_rows
    rows = []

    for record in records[data_start:]:
        if not record:
            continue

        first = record[0].lstrip("\ufeff")
        record = [first] + record[1:]

        if len(record) == 1 and not is_date_value(first):
            if re.match(
                r"^\s*(source|generated|exported|report)\s*:",
                first,
                re.IGNORECASE,
            ):
                continue

        rows.append(normalize(record))

    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    return {"columns": columns, "rows": rows}
